def cases():
    out = [(f"Range.{m}", f'v = Range("A1").{m}') for m in RANGE] + [(call.split(" ")[0][:40], call) for call in RANGE_CALLS]
    out += [(f"Worksheet.{m}", f"v = s.{m}") for m in SHEET] + [(call[:40], call) for call in SHEET_CALLS]
    out += [(f"Workbook.{m}", f"v = ActiveWorkbook.{m}") for m in BOOK] + [(call[:40], call) for call in BOOK_CALLS]
    out += [(f"Application.{m}", f"v = Application.{m}") for m in APP] + [(call[:40], call) for call in APP_CALLS]
    out += [(f"WorksheetFunction.{f}", f"v = WorksheetFunction.{f}({FUNCTION_ARGS[f]})") for f in FUNCTIONS]
    return out
